M=src/main/resources; J=src/main/java/net/officefloor/hq/app/patron; R=$M/officefloor/rest/api/sheets/{sheetId}; mkdir -p $J
cat > $M/db/migration/V22__person_patron.sql <<'EOF'
-- A person's patrons: other people on the same sheet, each named at most once. A person is never their own patron.
CREATE TABLE person_patron (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL REFERENCES person(id),
    patron_id BIGINT       NOT NULL REFERENCES person(id),
    PRIMARY KEY (person_id, patron_id),
    CHECK (person_id <> patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron(sheet_id);
EOF
cat > $J/Patron.java <<'EOF'
package net.officefloor.hq.app.patron;

/** A person's patron: another person on the same sheet, by id, with the patron's name. */
public record Patron(String sheetId, long personId, long patronId, String patronName) {
}
EOF
cat > $J/PatronResponse.java <<'EOF'
package net.officefloor.hq.app.patron;

/** A person's patron as the screen gets it: whose patron, and who (by id). */
public record PatronResponse(long personId, long patronId) {
